  rect(ctx,x+1,y+1,width-2,1,metal?'#f0f0f0':'#88c8ff');rect(ctx,x+1,y+2,1,height-3,metal?'#d0d8e0':'#68a8f8');
  rect(ctx,x+2,y+height-2,width-3,1,metal?'#505878':'#183878');
