  const dx=!reduced&&pose==='hit'?(Math.floor(tick)%4<2?-1:1):0;
  const y=8+bob, dark=player?'#183878':'#781838', light=player?'#88c8ff':'#ff98b0';
  fill(3,29,18,2,'#182838');
