  fill(3+dx,y+1,18,2,light); fill(3+dx,y+3,2,14,light);
  fill(5+dx,y+17,16,2,dark); fill(19+dx,y+3,2,14,dark);
  for(const x of [6,16]) { fill(x+dx,y+5,4,5,'#fff0d0'); fill(x+2+dx,y+6,2,pose==='hit'||pose==='lose'?1:3,'#282048'); }
